# French typography: narrow no-break space before ? ! ; : and inside « »
def _fr(v):
    if isinstance(v, str):
        for a, b in ((" ?", "\u202f?"), (" !", "\u202f!"), (" ;", "\u202f;"), (" :", "\u00a0:"), ("« ", "«\u00a0"), (" »", "\u00a0»")): v = v.replace(a, b)
        return v
    if isinstance(v, (list, tuple)): return type(v)(_fr(x) for x in v)
    if isinstance(v, dict): return {k: _fr(x) for k, x in v.items()}
    return v
